def interleave_3_to_1(functions,modules,limit=100):
    """Fixed, label-free mixing (not tuned on these 14 known fixes)."""
    out=[];i=j=0
    while len(out)<limit and (i<len(functions) or j<len(modules)):
        for _ in range(3):
            if i<len(functions) and len(out)<limit:
                out.append(functions[i]);i+=1
        if j<len(modules) and len(out)<limit:out.append(modules[j]);j+=1
        if i>=len(functions):
            while j<len(modules) and len(out)<limit:out.append(modules[j]);j+=1
    if len(set(map(candidate_id,out)))!=len(out):raise ValueError('M130_CANDIDATE_DUPLICATE')
    return out

def receipt_without_source(report: dict) -> dict:
    """No source, user goal, or matching query tokens enter the saved receipt."""
    if report.get("schema") != "SKYNETVS_M134_READONLY_PROJECT_CONTEXT_V1":
        raise ValueError("M134_REPORT_SCHEMA_INVALID")
    safe = {key: value for key, value in report.items()
            if not key.startswith("_private_") and key not in ("file_rank_top5", "contexts_metadata")}
    safe["file_rank_top5"] = [dict(path=w["path"],score=w["score"])
                              for w in report["file_rank_top5"]]
    safe["contexts_metadata"] = {}
    for budget, item in report["contexts_metadata"].items():
        stripped = {k:v for k,v in item.items() if k != "ranges"}
        stripped["ranges"] = [{k:v for k,v in window.items() if k != "matching_title_tokens"}
                              for window in item["ranges"]]
        safe["contexts_metadata"][budget] = stripped
    return safe

def find_git() -> Path:
    if os.name == "nt":
        candidates: list[Path] = []
        for key in ("ProgramW6432", "ProgramFiles", "ProgramFiles(x86)"):
            base = os.environ.get(key)
            if base:
                candidates.extend([Path(base) / "Git/cmd/git.exe", Path(base) / "Git/bin/git.exe"])
        local = os.environ.get("LOCALAPPDATA")
        if local:
            candidates.append(Path(local) / "Programs/Git/cmd/git.exe")
    else:
        found = shutil.which("git")
        candidates = [Path(found)] if found else []
    for path in candidates:
        if path.is_file():
            # Installed tool, not a name resolved from the project directory.
            return path.absolute()
    raise GitReadError("Установленный Git не найден в стандартных каталогах. Ничего не скачано. Учебный пример доступен без Git.")
